look.customCSS:
/* ───── 丑小鸭 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 52px 150px/44px 74px no-repeat,radial-gradient(circle at 74% 166px,#FFFDF2 0,#F6E3B0 19px,rgba(246,227,176,.4) 20.5px,rgba(246,227,176,.12) 55px,transparent 100px),radial-gradient(ellipse 100px 40px at 74% 200px,rgba(246,227,176,.28),transparent),url("data:image/svg+xml;base64,") 0 188px/200px 14px repeat-x,url("data:image/svg+xml;base64,") 0 40px/220px 170px repeat-x,linear-gradient(180deg,#0B1E2E 0,#2A5560 200px,#1C4C55 201px,#103138 55%,#091E24 100%) !important;background-color:#0C2A30 !important}
[data-wk="body"]{background:transparent !important;position:relative !important;z-index:1 !important;padding-top:118px !important}
[data-wk="chat"]{position:relative !important}
[data-wk="chat"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:200px !important;bottom:0 !important;background:url("data:image/svg+xml;base64,") 0 0/400px 580px repeat !important;pointer-events:none !important;z-index:0 !important}
[data-wk="chat"]::after{content:"" !important;position:absolute !important;left:calc(74% - 160px) !important;width:320px !important;top:201px !important;height:560px !important;background:url("data:image/svg+xml;base64,") 0 0/320px 560px no-repeat !important;-webkit-mask:linear-gradient(180deg,#000 30%,rgba(0,0,0,.4) 75%,transparent) !important;mask:linear-gradient(180deg,#000 30%,rgba(0,0,0,.4) 75%,transparent) !important;filter:blur(.7px) !important;pointer-events:none !important;z-index:0 !important}
[data-wk="chathead"],[data-wk="composer"]{position:relative !important;z-index:2 !important}

/* 顶栏：浮在夜空里的一块深色圆角牌，金色双线框（照参考），名字后面一行金色斜体书名 */
[data-wk="chathead"]{background:rgba(7,25,30,.82) !important;border:1px solid rgba(255,255,255,.28) !important;border-radius:14px !important;margin:6px 10px 0 !important;box-shadow:inset 0 0 0 3px rgba(7,25,30,.82),inset 0 0 0 3.6px rgba(242,178,74,.7),0 6px 18px rgba(0,0,0,.3) !important}
[data-wk="headink"],[data-wk="headink"] *{color:#F4F6F1 !important}
[data-wk="headname"] [data-wk="headink"]{font-family:Georgia,"Songti SC",serif !important;letter-spacing:.04em !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#93AFAE !important}
[data-wk="headname"] > div:last-child::before{content:"The Ugly Duckling · " !important;font:italic 11px/1 Georgia,serif !important;color:#E2A73C !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:110px !important}
[data-wk="chathead"] [data-wk="headname"] > div:last-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}
[data-wk="chatback"] svg{stroke:#F4F6F1 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important;flex-shrink:0 !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:6px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆的，白圈外再一圈金色微光 */
button[data-wk="avatar"],span[data-wk="avatar"],img[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),img[data-wk="avatar"]{box-shadow:0 0 0 3px #fff,0 0 0 5.4px #133B42,0 0 0 6.2px rgba(242,178,74,.9),0 0 16px rgba(255,255,255,.3) !important}
/* 顶栏双头像：两颗圆挨着，中间浮着一根小羽毛 */
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-8px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] img[data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-12px !important;bottom:-6px !important;width:16px !important;height:16px !important;z-index:3 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}

/* 气泡：浮在水上——他的白、柔光；我的青、半透，顶上一道高光、右下一道水纹。每串最后一条底下一截水里的倒影 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:13px !important;font-family:Georgia,"Songti SC",serif !important;letter-spacing:.06em !important;padding:11px 20px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;color:#0E3138 !important;border:1px solid #fff !important;box-shadow:0 0 16px rgba(255,255,255,.3) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30) 55%,rgba(155,231,236,.36)),rgba(18,66,75,.92) !important;color:#fff !important;border:1.2px solid rgba(255,255,255,.55) !important;border-top-color:rgba(255,255,255,.95) !important;border-left-color:rgba(255,255,255,.85) !important;box-shadow:none !important}
[data-wk="bubble"][data-kind="text"]::before{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;left:22px !important;top:4px !important;width:36px !important;height:2px !important;border-radius:2px !important;background:rgba(255,255,255,.45) !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:12px !important;bottom:4px !important;left:auto !important;top:auto !important;width:36px !important;height:8px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA4JyBmaWxsPSdub25lJyBzdHJva2U9J3JnYmEoMjMwLDI0NSwyNDAsLjYpJyBzdHJva2Utd2lkdGg9JzEuMicgc3Ryb2tlLWxpbmVjYXA9J3JvdW5kJz48cGF0aCBkPSdNMSAzIFE4IDcgMTYgMyBRMjQgMCAzOSA0Jy8+PHBhdGggZD0nTTggNi41IFExNCA4IDIyIDYnLz48L3N2Zz4=") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-last="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after,[data-wk="msg"]:not([data-last]) [data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;left:4px !important;right:4px !important;top:calc(100% + 4px) !important;height:22px !important;border-radius:0 0 18px 18px !important;background:linear-gradient(180deg,rgba(244,246,241,.22),rgba(244,246,241,0)) !important;-webkit-mask:repeating-linear-gradient(180deg,#000 0 3px,transparent 3px 5px) !important;mask:repeating-linear-gradient(180deg,#000 0 3px,transparent 3px 5px) !important;border:none !important;transform:none !important;pointer-events:none !important}
[data-last="1"][data-me="0"],[data-wk="msg"][data-me="0"][data-last="1"]{margin-bottom:14px !important}

/* 时间：不居中——左边一行「今天」小字，下面大一号的钟点，底下一道金线（照参考） */
[data-wk="time"]{text-align:left !important;justify-content:flex-start !important;padding-left:24px !important}
[data-wk="time"] > span{display:inline-block !important;background:transparent !important;border:none !important;border-bottom:1.5px solid #E2A73C !important;border-radius:0 !important;color:#F4F6F1 !important;font-family:Georgia,serif !important;font-size:15px !important;letter-spacing:.12em !important;padding:0 18px 6px 0 !important;text-shadow:0 0 8px rgba(255,255,255,.3) !important}

/* 已读：他的前面一只小鸭（白圆点＋橘嘴），我的后面一颗灰圆点 */
[data-wk="meta"]{background:rgba(11,39,45,.9) !important;box-shadow:0 0 8px 4px rgba(11,39,45,.9) !important;border-radius:8px !important;padding:0 4px !important;color:#93AFAE !important;font-size:10.5px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="msg"][data-me="0"] [data-wk="meta"]::before{content:"" !important;width:18px !important;height:11px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAxMic+PGNpcmNsZSBjeD0nNycgY3k9JzYnIHI9JzUnIGZpbGw9JyNGNEY2RjEnLz48cGF0aCBkPSdNMTIgNCBMMTggNiBMMTIgOFonIGZpbGw9JyNGMEEyM0EnLz48L3N2Zz4=") center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(255,255,255,.6)) !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]::before{content:"" !important;width:7px !important;height:7px !important;border-radius:50% !important;background:#93AFAE !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#93AFAE !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#F4F6F1 !important;border:none !important;border-radius:18px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#2D6B70 !important}

/* 动描：不进气泡——像湖面上一行被月光照着的字：不带框，两边各一道细水纹，淡金斜体 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{display:block !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA4JyBmaWxsPSdub25lJyBzdHJva2U9J3JnYmEoMjI2LDE2Nyw2MCwuNiknIHN0cm9rZS13aWR0aD0nMS4yJyBzdHJva2UtbGluZWNhcD0ncm91bmQnPjxwYXRoIGQ9J00xIDMgUTggNyAxNiAzIFEyNCAwIDM5IDQnLz48cGF0aCBkPSdNOCA2LjUgUTE0IDggMjIgNicvPjwvc3ZnPg==") left center/30px 8px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA4JyBmaWxsPSdub25lJyBzdHJva2U9J3JnYmEoMjI2LDE2Nyw2MCwuNiknIHN0cm9rZS13aWR0aD0nMS4yJyBzdHJva2UtbGluZWNhcD0ncm91bmQnPjxwYXRoIGQ9J00xIDMgUTggNyAxNiAzIFEyNCAwIDM5IDQnLz48cGF0aCBkPSdNOCA2LjUgUTE0IDggMjIgNicvPjwvc3ZnPg==") right center/30px 8px no-repeat !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#E8D7AE !important;opacity:1 !important;font-family:Georgia,"Songti SC",serif !important;font-style:italic !important;font-size:13px !important;line-height:1.85 !important;padding:6px 40px !important;text-align:center !important;text-shadow:0 0 8px rgba(0,0,0,.5) !important}
/* 系统提示：一行小字，前面一颗小星 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#93AFAE !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important}
[data-wk="sysnotetext"]::before{content:"✧ " !important;color:#E2A73C !important}

/* 底栏：同顶栏一块深色圆角牌，金色双线；加号是一颗裂开的蛋，回复是一片睡莲叶，发送是小鸭的脑袋＋橘色小嘴 */
[data-wk="composer"]{background:rgba(7,25,30,.82) !important;border:1px solid rgba(255,255,255,.28) !important;border-radius:14px !important;margin:0 10px 8px !important;box-shadow:inset 0 0 0 3px rgba(7,25,30,.82),inset 0 0 0 3.6px rgba(242,178,74,.7) !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:linear-gradient(180deg,#24525A,#1A3F46) !important;border:1px solid rgba(190,230,225,.4) !important;border-radius:16px !important;color:#F4F6F1 !important}
[data-wk="chatinput"]::placeholder{color:#93AFAE !important}
[data-wk="chatplus"]{width:28px !important;min-width:28px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:none !important;rotate:none !important}
[data-wk="send"]{width:52px !important;min-width:52px !important;height:36px !important;border:none !important;border-radius:0 !important;box-shadow:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important;filter:drop-shadow(0 0 8px rgba(255,255,255,.55)) !important}
[data-wk="chatreply"]{width:38px !important;min-width:38px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
/* ───── 丑小鸭 · 第二批：卡片（形状不动；他的白瓷、我的水色玻璃，同气泡；细金线收边） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:14px !important;box-shadow:0 0 16px rgba(255,255,255,.28),inset 0 0 0 4px #F7FAF9,inset 0 0 0 4.6px rgba(242,178,74,.55) !important;color:#0E3138 !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *{color:#0E3138 !important;border-color:rgba(14,49,56,.15) !important}
/* 转账：白瓷卡，金额金色衬线；收下盖一枚金色羽毛圆章 */
[data-wk="transferamount"],[data-wk="transfercur"]{color:#C98A1E !important;font-family:Georgia,serif !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:linear-gradient(90deg,transparent,#F2B24A,transparent) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:rgba(18,66,75,.06) !important;border-top:1px solid rgba(14,49,56,.12) !important}
[data-wk="transferbtn"]{border-radius:12px !important}
[data-wk="transferbtn"][data-part="take"]{background:#12424B !important;color:#fff !important;border:1px solid #fff !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;border:1px solid rgba(14,49,56,.3) !important}
[data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;width:44px !important;height:44px !important;font-size:0 !important;color:transparent !important}
[data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-10deg) !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.55 !important}
/* 红包：不是信封——一块水色玻璃，左边卧着一颗金蛋（丑小鸭的蛋）；领完蛋壳裂开变淡 */
[data-wk="rpcard"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30) 55%,rgba(155,231,236,.36)),rgba(18,66,75,.95) !important;border:1.2px solid rgba(255,255,255,.6) !important;border-top-color:rgba(255,255,255,.95) !important;padding-left:58px !important;box-shadow:inset 0 0 0 4px #2A6670,inset 0 0 0 4.6px rgba(242,178,74,.6) !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:calc(50% - 22px) !important;width:38px !important;height:44px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 8px rgba(246,210,122,.6)) !important;z-index:2 !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{opacity:.6 !important}
[data-wk="rpcard"][data-status="done"]::before{filter:grayscale(.6) !important}
[data-wk="rpenvelope"]{background:radial-gradient(circle at 70% 18%,#FFFDF2 0 18px,rgba(246,227,176,.3) 20px,transparent 70px),linear-gradient(180deg,#0B1E2E,#2A5560 45%,#1C4C55 46%,#091E24) !important;border:1px solid rgba(255,255,255,.4) !important;border-radius:18px !important;box-shadow:inset 0 0 0 4px #10283A,inset 0 0 0 4.6px rgba(242,178,74,.7),0 10px 30px rgba(0,0,0,.5) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#fff !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 0 12px rgba(246,210,122,.7)) !important}
[data-wk="rpopenbtn"] *{opacity:0 !important}
[data-wk="rpamount"]{color:#FFF3CF !important;font-family:Georgia,serif !important;text-shadow:0 0 10px rgba(246,227,176,.6) !important}
/* 照片：白瓷框里一块湖色小屏；语音：水色玻璃条，波形是奶油色 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:10px !important;background:linear-gradient(180deg,#1C4C55,#103138) !important;border:none !important}
[data-wk="photoface"] *,[data-wk="photohint"]{color:#E8F1F0 !important}
[data-wk="photoface"] svg{stroke:#FFF3CF !important}
[data-wk="voice"][data-me]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:13px !important;box-shadow:0 0 14px rgba(255,255,255,.28) !important}
[data-wk="voice"][data-me="1"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30)),rgba(18,66,75,.92) !important;border-color:rgba(255,255,255,.6) !important;box-shadow:none !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#0E3138 !important}
[data-wk="voice"][data-me="1"] > *{color:#fff !important}
[data-wk="voicewave"] span{background:#3FA2B0 !important}
[data-wk="voice"][data-me="1"] [data-wk="voicewave"] span{background:#FFF3CF !important}
/* 天气、位置、名片 */
[data-wk="wxcard"]{background:linear-gradient(180deg,#0B1E2E,#1C4C55) !important;border:1px solid rgba(255,255,255,.4) !important;box-shadow:inset 0 0 0 4px #10283A,inset 0 0 0 4.6px rgba(242,178,74,.6) !important}
[data-wk="wxcard"] *{color:#fff !important}
[data-wk="wxcardsky"]{background:transparent !important}
[data-wk="wxcardsky"] > div:first-child{background:radial-gradient(circle,#FFFDF2 0 12px,rgba(246,227,176,.35) 14px,transparent 60%) !important}
[data-wk="wxcardsky"] svg{stroke:#FFF3CF !important}
[data-wk="wxcardsky"] span[style*="999"],[data-wk="wxcardrain"]{background:rgba(255,255,255,.1) !important;border:1px solid rgba(255,255,255,.35) !important}
[data-wk="wxcardtemp"]{font-family:Georgia,serif !important}
[data-wk="wxcardsay"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border-top:none !important;border-radius:0 0 13px 13px !important}
[data-wk="wxcardsay"],[data-wk="wxcardsay"] *{color:#0E3138 !important}
[data-wk="geopin"]{background:#F2B24A !important;box-shadow:0 0 0 2px #fff,0 0 10px #F2B24A !important}
[data-wk="geopinstem"]{background:#fff !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2.5px #fff,0 0 0 3.4px #F2B24A !important}
/* 拍一拍、通话结束：一行奶油色小字，两头各一道细水纹 */
